from typing import List

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    # Normalize lengths by left-padding with zeros so we can XOR position-wise
    maxlen = max(len(a), len(b))
    a_padded = a.zfill(maxlen)
    b_padded = b.zfill(maxlen)

    # Validate inputs contain only '0' or '1'
    for ch in a_padded:
        if ch not in ("0", "1"):
            raise ValueError(f"Invalid character in first input: {ch}")
    for ch in b_padded:
        if ch not in ("0", "1"):
            raise ValueError(f"Invalid character in second input: {ch}")

    # Compute XOR character by character
    result_chars = []
    for ca, cb in zip(a_padded, b_padded):
        result_chars.append("1" if ca != cb else "0")

    return "".join(result_chars)

def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """
    if n < 0:
        return ''
    return ' '.join(str(i) for i in range(0, n + 1))

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result_chars = []
    for c in string:
        if c.islower():
            result_chars.append(c.upper())
        elif c.isupper():
            result_chars.append(c.lower())
        else:
            result_chars.append(c)
    return ''.join(result_chars)

