def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    try:
        # Fast path for hashable elements
        return sorted(set(l))
    except TypeError:
        # Fallback for unhashable elements: preserve uniqueness by membership check
        unique_list = []
        for item in l:
            if item not in unique_list:
                unique_list.append(item)
        return sorted(unique_list)

def encode_cyclic(s: str) -> str:
    """
    Returns encoded string by cycling every group of three characters to the left by one.
    Groups with fewer than 3 characters (at the end) are left unchanged.
    Example: "abcdefg" -> "bcaefd g" -> "bc a fe dg"? (Clarification: For "abcdefg" -> "bcaefd g" -> "bc a fe dg"?)
    """
    out = []
    for i in range(0, len(s), 3):
        g = s[i:i+3]
        if len(g) == 3:
            # rotate left by one
            out.append(g[1:] + g[0])
        else:
            out.append(g)
    return "".join(out)


def decode_cyclic(s: str) -> str:
    """
    Reverses encode_cyclic: for each full 3-character group, rotate right by one.
    Partial groups are left unchanged.
    """
    out = []
    for i in range(0, len(s), 3):
        g = s[i:i+3]
        if len(g) == 3:
            # rotate right by one (inverse of left rotation)
            out.append(g[-1] + g[:-1])
        else:
            out.append(g)
    return "".join(out)

