def is_simple_power(x, n):
    """Return True if there exists a non-negative integer k such that n**k == x."""
    # Special handling for x == 1: n**0 == 1 for any n != 0
    if x == 1:
        return n != 0

    # Handle small set of bases that need special logic
    if n == 1:
        # Only 1**k == 1
        return x == 1
    if n == -1:
        # (-1)**k is 1 for even k and -1 for odd k
        return x == 1 or x == -1
    if n == 0:
        # 0**k == 0 for k >= 1
        return x == 0

    # If x == 0, it could only be a power of 0 (handled above), otherwise impossible
    if x == 0:
        return False

    # For other n, repeatedly divide x by n while divisible
    value = x
    # Keep dividing while divisible by n
    while value % n == 0:
        value = value // n
        if value == 1:
            return True

    return False

