    You need to find the largest prime value and return the sum of its digits.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        # check 6k-1 and 6k+1 up to sqrt(n)
        limit = math.isqrt(n)
        i = 5
        while i <= limit:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_prime = None
    for x in lst:
        # Only consider integers > 1
        if isinstance(x, int) and x > 1 and is_prime(x):
            if largest_prime is None or x > largest_prime:
                largest_prime = x

    if largest_prime is None:
        return 0

    # Sum digits of the largest prime (handle positive integers)
    return sum(int(ch) for ch in str(abs(largest_prime)))

