def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in the Collatz sequence.

    The Collatz sequence: start with n. If the term is even, next term = term // 2.
    If the term is odd, next term = 3 * term + 1. Repeat until reaching 1.

    Returns a sorted list (in increasing order) of all odd numbers that appear in the sequence,
    including the starting n if it is odd and the final 1.

    Raises ValueError if n is not a positive integer.
    """
    if not isinstance(n, int) or isinstance(n, bool) or n <= 0:
        raise ValueError("n must be a positive integer")

    odds = set()
    current = n

    while True:
        if current % 2 == 1:
            odds.add(current)
        if current == 1:
            break
        if current % 2 == 0:
            current //= 2
        else:
            current = 3 * current + 1

    return sorted(odds)

