from typing import Any, Optional
from decimal import Decimal, InvalidOperation


def compare_one(a: Any, b: Any) -> Optional[Any]:
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    def to_decimal(x: Any) -> Decimal:
        # Convert various input types to a Decimal for accurate comparison.
        if isinstance(x, str):
            s = x.strip().replace(',', '.')
            # Let Decimal raise InvalidOperation if s is not a valid number
            return Decimal(s)
        if isinstance(x, int):
            return Decimal(x)
        if isinstance(x, float):
            # Use from_float to get the exact decimal representation of the float
            return Decimal.from_float(x)
        # Fallback: try to convert via string representation
        return Decimal(str(x))

    try:
        da = to_decimal(a)
        db = to_decimal(b)
    except (InvalidOperation, ValueError):
        # If conversion to Decimal fails, fall back to safe float parsing and comparison
        def to_float(x: Any) -> float:
            if isinstance(x, str):
                return float(x.strip().replace(',', '.'))
            return float(x)
        na = to_float(a)
        nb = to_float(b)
        if na == nb:
            return None
        return a if na > nb else b

    if da == db:
        return None
    return a if da > db else b

