def find_max(words):
    """Return the word with the maximum number of unique characters.
    If multiple words have the same maximum number of unique characters,
    return the lexicographically smallest one. If the input list is empty,
    return an empty string.
    """
    if not words:
        return ""
    # Determine the maximum number of unique characters in any word.
    max_count = 0
    for w in words:
        unique_count = len(set(w))
        if unique_count > max_count:
            max_count = unique_count
    # Collect all words that have that maximum unique character count.
    candidates = [w for w in words if len(set(w)) == max_count]
    # Return the lexicographically smallest among the candidates.
    return min(candidates)

from typing import List

def do_algebra(operator: List[str], operand: List[int]):
    """
    Given two lists operator, and operand. The first list has basic algebra operations, and 
    the second list is a list of integers. Use the two given lists to build the algebraic 
    expression and return the evaluation of this expression.

    Supported operators: '+', '-', '*', '//', '**'
    """
    # Build token list: alternating ints and operator strings
    tokens = []
    tokens.append(int(operand[0]))
    for i, op in enumerate(operator):
        tokens.append(op)
        tokens.append(int(operand[i + 1]))

    # Precedence and associativity
    precedence = {
        '**': 4,
        '*': 3,
        '//': 3,
        '+': 2,
        '-': 2
    }
    # True means left-associative, False means right-associative
    left_assoc = {
        '**': False,
        '*': True,
        '//': True,
        '+': True,
        '-': True
    }

    # Shunting-yard: convert infix tokens to RPN
    output_queue = []
    op_stack = []

    for tok in tokens:
        if isinstance(tok, int):
            output_queue.append(tok)
        else:
            # tok is an operator string
            while op_stack:
                top = op_stack[-1]
                if top not in precedence:
                    break
                # Compare precedence and associativity
                if (left_assoc.get(tok, True) and precedence[tok] <= precedence[top]) or \
                   (not left_assoc.get(tok, True) and precedence[tok] < precedence[top]):
                    output_queue.append(op_stack.pop())
                else:
                    break
            op_stack.append(tok)

    while op_stack:
        output_queue.append(op_stack.pop())

    # Evaluate RPN
    def apply_op(a, b, op):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '//':
            return a // b
        if op == '**':
            return a ** b
        raise ValueError(f"Unsupported operator: {op}")

    stack = []
    for tok in output_queue:
        if isinstance(tok, int):
            stack.append(tok)
        else:
            # operator: pop right then left
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            a = stack.pop()
            stack.append(apply_op(a, b, tok))

    if len(stack) != 1:
        raise ValueError("Invalid evaluation state")

    return stack[0]
